mapper.select:
select c.*

    ,vi.video_name, vi.video_cover, u.user_name, u.avatar, u2.user_name replyUserName

from pilipili.video_comment c

    inner join pilipili.video_info vi on c.video_id = vi.video_id
    left join pilipili.user u on c.user_id = u.user_id
    left join pilipili.user u2 on c.reply_user_id = u2.user_id



        c.video_id = #{videoId}


        and c.video_user_id = #{videoUserId}


        and vi.video_name like concat('%', #{videoNameFuzzy}, '%')



    order by ${orderByField}

select v.*, u.user_name userName, u.avatar
from video_comment v
inner join pilipili.user u on v.user_id = u.user_id
where p_comment_id = #{pCommentId} and video_id = #{videoId}

    and top_type = #{topType}


    order by ${orderByField}

